import React from 'react';
import {  Lock, Bell } from 'lucide-react';

const StudentSettings = () => {
  return (
    <div className="p-8 text-right" dir="rtl">
      <h1 className="text-2xl font-bold mb-8">الإعدادات</h1>
      <div className="max-w-2xl bg-white rounded-2xl shadow-sm p-6 space-y-6">
        <div className="flex items-center justify-between p-4 bg-slate-50 rounded-xl">
          <div className="flex items-center gap-4"><Lock className="text-slate-400"/><span>تغيير كلمة المرور</span></div>
          <button className="text-blue-600 font-bold">تعديل</button>
        </div>
        <div className="flex items-center justify-between p-4 bg-slate-50 rounded-xl">
          <div className="flex items-center gap-4"><Bell className="text-slate-400"/><span>إشعارات البريد</span></div>
          <input type="checkbox" className="w-5 h-5 accent-blue-600" checked />
        </div>
      </div>
    </div>
  );
};
export default StudentSettings;
